using System.ComponentModel;
using System.Text.Json;

/// <summary>
/// Tools exposed to the research agent for web searching and note-taking.
/// </summary>
public static class ResearchTools
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
    };

    private static readonly List<(string Label, string Content)> s_notes = [];

    [Description("Search the web for information using DuckDuckGo. Returns a summary of results.")]
    public static async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_httpClient.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var parts = new List<string>();

            // Abstract (main instant answer)
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                parts.Add($"Summary ({abstractSource}): {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 5)
                        break;

                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        parts.Add($"- {text}");
                        count++;
                    }
                }
            }

            // Answer (computational / factual)
            var answer = root.GetProperty("Answer").GetString();
            if (!string.IsNullOrWhiteSpace(answer))
            {
                parts.Add($"Answer: {answer}");
            }

            return parts.Count > 0
                ? string.Join("\n", parts)
                : $"No instant-answer results for '{query}'. Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note with a label for later reference.")]
    public static string SaveNote(
        [Description("The note content to save")] string content,
        [Description("A short descriptive label for the note")] string label)
    {
        s_notes.Add((label, content));
        return $"Note saved under '{label}' ({s_notes.Count} total notes).";
    }

    [Description("Retrieve all previously saved research notes.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return string.Join("\n", s_notes.Select((n, i) =>
            $"{i + 1}. [{n.Label}] {n.Content}"));
    }
}

