using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Build the chat client through the MEAI abstraction layer.
IChatClient chatClient = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(modelId)
    .AsIChatClient();

// Create AI-callable tool functions from the static helper methods.
var tools = new AITool[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

// Configure the agent with a system prompt, tools, and guardrails.
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly
        by using your tools, then produce a clear summary.

        Workflow:
        1. Break the topic into 2-3 focused search queries.
        2. For each query, call SearchWeb and review the results.
        3. Save important findings with SaveNote (use a short descriptive label).
        4. After gathering enough information, call GetNotes to review everything.
        5. Produce a well-structured summary with key facts and source context.

        Be thorough but concise. Cite the information you found.
        """)
{
    Tools = tools,
};

// Ask the user for a research topic.
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent with iteration and token guardrails.
var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

await foreach (var response in agent.InvokeStreamingAsync(history, options))
{
    if (response.Role == ChatRole.Assistant && !string.IsNullOrEmpty(response.Text))
    {
        Console.Write(response.Text);
    }
}

Console.WriteLine();

